using Microsoft.EntityFrameworkCore;using MongoDB.Driver;using ZosyalMedya.BuildingBlocks.Domain;using ZosyalMedya.Modules.Notifications.Application.Inbox;using ZosyalMedya.Modules.Notifications.Application.Ports;using ZosyalMedya.Modules.Notifications.Contracts;using ZosyalMedya.Modules.Notifications.Infrastructure.Persistence.MongoDb;using ZosyalMedya.Modules.Notifications.Infrastructure.Persistence.PostgreSql;using Xunit;
namespace ZosyalMedya.Tests.Integration.Persistence;
public abstract class NotificationRepositoryContractTests
{protected abstract Task<INotificationRepository>CreateRepositoryAsync();[Fact]public async Task AggregationCursorReadAndDeliveryBehaveEqually(){if(!InfrastructureTestGate.IsEnabled)return;var repository=await CreateRepositoryAsync();var now=new DateTimeOffset(2026,7,12,16,0,0,TimeSpan.Zero);var clock=new FixedClock(now);var module=new NotificationsModule(repository,new SilentRealtime(),clock);var recipient=Guid.NewGuid();var key=$"contract:{Guid.NewGuid():N}";var command=new EnqueueNotification(recipient,Guid.NewGuid(),"Message",Guid.NewGuid(),key,"title","body",1,new Dictionary<string,string>{{"preview","a"}},"/mesajlar");await module.EnqueueAsync(command);await module.EnqueueAsync(command with{Arguments=new Dictionary<string,string>{{"preview","b"}}});var aggregated=await repository.FindUnreadAggregationAsync(new(recipient),key);Assert.NotNull(aggregated);Assert.Equal(2,aggregated.Count);var page=await repository.ListPageAsync(new(new(recipient),null,null,1));Assert.Single(page);Assert.Single(await repository.ListDueDeliveriesAsync(now,10));var version=aggregated.Version;aggregated.MarkRead(now.AddMinutes(1));Assert.True(await repository.UpdateAsync(x=>x.Id==aggregated.Id,aggregated,version));Assert.Null(await repository.FindUnreadAggregationAsync(new(recipient),key));Assert.Equal(1,await repository.DeleteByFilterAsync(x=>x.Id==aggregated.Id));}private sealed class FixedClock(DateTimeOffset now):IClock{public DateTimeOffset UtcNow=>now;}private sealed class SilentRealtime:IRealtimeNotificationPublisher{public Task PublishAsync(Guid recipientId,object payload,CancellationToken cancellationToken=default)=>Task.CompletedTask;}}
public sealed class PostgreSqlNotificationRepositoryContractTests:NotificationRepositoryContractTests{protected override async Task<INotificationRepository>CreateRepositoryAsync(){var db=new NotificationsDbContext(new DbContextOptionsBuilder<NotificationsDbContext>().UseNpgsql("Host=localhost;Port=55432;Database=zosyalmedya;Username=zosyalmedya;Password=local_only_change_me").Options);await db.Database.MigrateAsync();return new PostgreSqlNotificationRepository(db);}}
public sealed class MongoNotificationRepositoryContractTests:NotificationRepositoryContractTests{protected override async Task<INotificationRepository>CreateRepositoryAsync(){var repository=new MongoNotificationRepository(new MongoClient("mongodb://localhost:57017").GetDatabase("zosyalmedya_contract_tests"));await repository.EnsureIndexesAsync(CancellationToken.None);return repository;}}
